CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, password_hash text NOT NULL, role text NOT NULL DEFAULT 'admin', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS social_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id) ON DELETE CASCADE, provider text NOT NULL, external_id text NOT NULL, name text NOT NULL, access_token_encrypted text, token_expires_at timestamptz, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider, external_id));
CREATE TABLE IF NOT EXISTS posts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id) ON DELETE SET NULL, title text NOT NULL, content text NOT NULL, status text NOT NULL DEFAULT 'DRAFT', scheduled_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS post_targets (post_id uuid REFERENCES posts(id) ON DELETE CASCADE, social_account_id uuid REFERENCES social_accounts(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'PENDING', external_post_id text, error text, published_at timestamptz, PRIMARY KEY(post_id, social_account_id));
CREATE TABLE IF NOT EXISTS media (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id) ON DELETE SET NULL, object_key text NOT NULL UNIQUE, mime_type text, size_bytes bigint, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS campaigns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, status text NOT NULL DEFAULT 'DRAFT', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS analytics (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), social_account_id uuid REFERENCES social_accounts(id) ON DELETE CASCADE, metric_date date NOT NULL, impressions bigint DEFAULT 0, reach bigint DEFAULT 0, likes bigint DEFAULT 0, comments bigint DEFAULT 0, shares bigint DEFAULT 0, raw jsonb NOT NULL DEFAULT '{}', UNIQUE(social_account_id, metric_date));
CREATE TABLE IF NOT EXISTS ai_generations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id) ON DELETE SET NULL, prompt text NOT NULL, response jsonb NOT NULL, provider text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id) ON DELETE SET NULL, action text NOT NULL, resource text, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
